class Solution {
  public int maxSum(int[] nums) {
    Set<Integer> positives = new HashSet<>();
    int max = Integer.MIN_VALUE;
    for (int x : nums) {
      max = Math.max(max, x);
      if (x > 0) positives.add(x);
    }
    if (positives.isEmpty()) return max;
    int sum = 0;
    for (int x : positives) sum += x;
    return sum;
  }
}
